<h2><?=$title?></h2><div class="card"><div class="card-body"><?=form_open()?><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Nomor Invoice</label><input required class="form-control" name="invoice_number" value="<?=html_escape($invoice->invoice_number??'')?>" <?= $invoice?'readonly':''?>></div><div class="col-md-4 mb-3"><label class="form-label">Tanggal Invoice</label><input required type="date" class="form-control" name="invoice_date" value="<?=$invoice->invoice_date??date('Y-m-d')?>"></div><?php if(!$invoice):?><div class="col-md-4 mb-3"><label class="form-label">Purchase Order</label><select required id="po" class="form-select" name="po_id"><?php foreach($pos as $p):?><option value="<?=$p->po_id?>"><?=$p->po_number?> - <?=$p->vendor?></option><?php endforeach;?></select></div><?php endif;?></div><?php if(!$invoice):?><table class="table"><tr><th>PO</th><th>Part Number</th><th>Description</th><th>Qty PO</th><th>Harga</th><th>Qty Invoice</th></tr><?php foreach($items as $i):?><tr class="po-item" data-po="<?=$i->po_id?>"><td><?=$i->po_number?></td><td><?=$i->part_number?></td><td><?=$i->description?></td><td><?=$i->qty?></td><td><?=rupiah($i->unit_price)?></td><td><input class="form-control" type="number" min="0" max="<?=$i->qty?>" step="0.01" name="qty[<?=$i->po_item_id?>]"></td></tr><?php endforeach;?></table><script>function filterItems(){document.querySelectorAll('.po-item').forEach(r=>r.style.display=r.dataset.po===document.getElementById('po').value?'':'none')}document.getElementById('po').addEventListener('change',filterItems);filterItems();</script><?php endif;?><button class="btn btn-primary">Simpan</button><a class="btn btn-light" href="<?=site_url('invoices')?>">Batal</a><?=form_close()?></div></div>
